  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B009",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have transformed precision measurement, reached extraordinary reproducibility, and enable broad tests and applications.",
        "attribution": "Katori supplied the decisive magic-wavelength lattice-clock concept; Ye made foundational experimental advances and field-defining realizations.",
        "maturity": "The principle and performance have been repeatedly established across laboratories over many years.",
        "uncertainties": [
          "The eventual scope of applications such as relativistic geodesy and redefinition of the second remains partly prospective."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Christian J. Bordé",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry created a remarkably sensitive quantum-measurement platform with fundamental and practical consequences.",
        "attribution": "Bordé developed central light-pulse interferometric concepts, while Kasevich established powerful precision experiments and instruments.",
        "maturity": "Its measurement principles are mature, reproducible, and deployed in precision gravimetry and tests of physics.",
        "uncertainties": [
          "Credit for the many foundational atom-interferometry developments is inherently broad."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic band gaps supplied a new way to control light with structured matter and opened a durable experimental and technological field.",
        "attribution": "John articulated the localization and band-gap vision, while Yablonovitch gave decisive conceptual and experimental impetus.",
        "maturity": "The field has had decades to demonstrate control of emission, propagation, and integrated optical structures.",
        "uncertainties": [
          "The relative place of theoretical and experimental contributors, including Joannopoulos, needs careful historical assessment."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B010",
      "proposed_laureates": [
        "Jörg Wrachtrup",
        "Fedor Jelezko",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Coherent diamond-spin control made a robust solid-state quantum sensor and a major platform for quantum science.",
        "attribution": "Wrachtrup and Jelezko were central to optical detection and coherent control; Lukin made influential contributions to the wider quantum-platform development.",
        "maturity": "Single-spin sensing and coherent manipulation are extensively replicated and already useful in demanding measurement settings.",
        "uncertainties": [
          "The candidate combines several intertwined advances, making a sharply bounded prize formulation difficult."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B005",
      "proposed_laureates": [
        "John M. Doyle",
        "Jun Ye",
        "David DeMille"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum control of ultracold molecules has expanded AMO physics toward precision tests, chemistry, and many-body quantum matter.",
        "attribution": "Doyle pioneered key cooling methods, while Ye and DeMille made major advances in controlled molecular platforms and precision applications.",
        "maturity": "The experimental toolbox is now convincing and productive, though less settled as a single defining discovery than atomic cooling.",
        "uncertainties": [
          "The field's credit is broad and overlaps substantially with direct laser cooling of molecules."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Charles H. Bennett",
        "Gilles Brassard",
        "Artur Ekert"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum cryptography established a profound operational use of quantum measurement and stimulated a major experimental field.",
        "attribution": "Bennett and Brassard originated the seminal protocol; Ekert supplied an independently foundational entanglement-based formulation.",
        "maturity": "Security concepts and practical demonstrations have been tested over decades, including realistic communication systems.",
        "uncertainties": [
          "The practical security of implementations depends on device assumptions and continues to evolve."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B001",
      "proposed_laureates": [
        "John B. Pendry",
        "David R. Smith",
        "Federico Capasso"
      ],
      "assessment": {
        "nobel_worthiness": "Metamaterials and metasurfaces provided powerful new control of electromagnetic waves and have had major conceptual and technological influence.",
        "attribution": "Pendry developed key theoretical ideas, Smith made landmark microwave demonstrations, and Capasso advanced influential optical implementations.",
        "maturity": "The underlying wave-control physics is established and has generated many reproducible devices.",
        "uncertainties": [
          "Some early transformative claims, especially around negative refraction and cloaking, exceeded subsequent practical performance."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B041",
      "proposed_laureates": [
        "Markus Aspelmeyer",
        "Tobias J. Kippenberg",
        "Andrew N. Cleland"
      ],
      "assessment": {
        "nobel_worthiness": "Ground-state mechanical control makes quantum behavior accessible in engineered macroscopic devices and advances precision measurement.",
        "attribution": "Aspelmeyer, Kippenberg, and Cleland each made central experimental and conceptual contributions to quantum optomechanics.",
        "maturity": "Ground-state preparation and coherent control have been achieved in several architectures, with an increasingly reliable experimental base.",
        "uncertainties": [
          "Its ultimate enabling impact beyond specialist laboratories is still emerging."
        ]
      }
    }
  ]
}
